        "step": "Synthesis & Reporting",
        "actions": [
          "Populate a comparative matrix using the evaluation dimensions.",
          "Highlight gaps, trade\u2011offs, and risk factors for DataPulse Systems vs. CloudScale AI."
        ]
      }
    ]
  }
}

